"use client";
import {CashierBankTransit} from './cashier-bank-transit';
import {CashierBankCloseReview} from './cashier-bank-close-review';
import {CashierBankSettlementReview} from './cashier-bank-settlement-review';
import {CashierBankMatchReverse} from './cashier-bank-match-reverse';
import {CashierBankMatchCreate} from './cashier-bank-match-create';
import {CashierBankStatementRegister} from './cashier-bank-statement-register';
import {CashierBankStatementCreate} from './cashier-bank-statement-create';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,type Membership} from '@/lib/pilot';
import {readBankAccounts} from '@/lib/cashier-bank-deposits';
import {readMatchHistory,readReconciliationSummary} from '@/lib/cashier-bank-reconciliation';
const money=(value:string)=>{const n=BigInt(value);return '$'+(n/BigInt(100)).toLocaleString('en-US')+'.'+(n%BigInt(100)).toString().padStart(2,'0')};
export function CashierBankReconciliation({membership}:{membership:Membership}){return membership.role==='owner'||membership.role==='manager'?<Report key={[membership.tenant_id,membership.property_id,membership.role].join(':')} membership={membership}/>:null}
function Report({membership}:{membership:Membership}){
 const [statementVersion,setStatementVersion]=useState(0),[closeVersion,setCloseVersion]=useState(0);
 const [accounts,setAccounts]=useState<ReturnType<typeof readBankAccounts>|null>(null),[account,setAccount]=useState(''),[actor,setActor]=useState(''),[history,setHistory]=useState<ReturnType<typeof readMatchHistory>|null>(null),[totals,setTotals]=useState<ReturnType<typeof readReconciliationSummary>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const alive=useRef(false),lock=useRef(false),refreshQueued=useRef(false),activeKind=useRef('');useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 async function load(kind:'accounts'|'report',next=false){if(lock.current){if(kind==='report'&&activeKind.current==='report'&&!next)refreshQueued.current=true;return;}if(kind==='report')setCloseVersion(v=>v+1);activeKind.current=kind;lock.current=true;setBusy(true);setError('');try{
  const user=await hotelClient().auth.getUser();if(user.error||!user.data.user)throw Error('Sign in to view reconciliation.');const id=user.data.user.id;if(actor&&id!==actor)throw Error('Sign-in changed. Reload the page.');const scope={tenant:membership.tenant_id,property:membership.property_id,actor:id};const args={p_tenant:scope.tenant,p_property:scope.property};
  if(kind==='accounts'){
   const result=readBankAccounts(await hotelRpc('cashier_bank_accounts',{...args,p_before:next?accounts?.next??null:null}),scope,next?accounts?.next??null:null);
   const check=await hotelClient().auth.getUser();if(check.error||check.data.user?.id!==id)throw Error('Sign-in changed. Reload the page.');if(alive.current){setActor(id);setAccounts(result);setAccount('');setHistory(null);setTotals(null)}
  }else{
   if(!account)throw Error('Choose a bank account.');const before=next?history?.next??null:null;
   const result=readMatchHistory(await hotelRpc('cashier_bank_match_history',{...args,p_account:account,p_before:before}),scope,account,before);
   const summary=readReconciliationSummary(await hotelRpc('cashier_bank_reconciliation_summary',{...args,p_account:account}),scope,account);
   const check=await hotelClient().auth.getUser();if(check.error||check.data.user?.id!==id)throw Error('Sign-in changed. Reload the page.');if(alive.current){setActor(id);setHistory(result);setTotals(summary)}
  }
 }catch(e){if(alive.current){setHistory(null);setTotals(null);setError(e instanceof Error?e.message:'Unable to load reconciliation.')}}finally{lock.current=false;if(alive.current){setBusy(false);if(refreshQueued.current){refreshQueued.current=false;void load('report')}}}}
 return <section className="card"><h2>Deposit reconciliation</h2><p>Matches to manually entered statement credits. This view does not confirm bank receipt or post accounting entries. Totals and history refresh independently as records change.</p><button disabled={busy} onClick={()=>void load('accounts')}>Refresh reconciliation accounts</button>{accounts&&<><label>Bank account<select disabled={busy} value={account} onChange={e=>{setAccount(e.target.value);setHistory(null);setTotals(null)}}><option value="">Choose an account</option>{accounts.entries.map(a=><option key={a.id} value={a.id}>{a.label} ({a.code})</option>)}</select></label>{accounts.entries.length===0&&<p>No accounts on this page.</p>}{accounts.next&&<button disabled={busy} onClick={()=>void load('accounts',true)}>Next account page</button>}<button disabled={busy||!account} onClick={()=>void load('report')}>Refresh reconciliation</button></>}{actor&&account&&<CashierBankMatchCreate key={"match:"+actor+":"+account} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} account={account} onSaved={()=>void load('report')}/>}{actor&&account&&<CashierBankStatementRegister key={"register:"+actor+":"+account} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} account={account} refreshVersion={statementVersion} onChanged={()=>void load('report')}/>}{actor&&account&&<CashierBankStatementCreate key={actor+":"+account} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} account={account} onSaved={()=>{setStatementVersion(v=>v+1);void load('report')}}/>}{actor&&account&&<CashierBankTransit key={"transit:"+actor+":"+account+":"+closeVersion} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} bank={account}/>}{actor&&account&&<CashierBankCloseReview key={"close:"+actor+":"+account+":"+closeVersion} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} bank={account}/>}{error&&<p role="alert">{error}</p>}{totals&&<dl>{Object.entries({Deposits:totals.deposits,'Statement credits':totals.credits,'Active matches':totals.matched,'Unmatched deposits':totals.unmatchedDeposits,'Unmatched credits':totals.unmatchedCredits,'Unreviewed statement debits':totals.debits,'Reversed match amounts':totals.reversed}).map(([label,value])=><div key={label}><dt>{label}</dt><dd>{money(value)}</dd></div>)}</dl>}{history&&<><h3>Match history</h3>{history.entries.length?<div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Amount</th><th>Status</th><th>Explanation</th><th>References</th></tr></thead><tbody>{history.entries.map(m=><tr key={m.id}><td>{money(m.amount)}</td><td>{m.status==='active'?'Active':'Reversed'}</td><td>{m.reason}{m.reversalReason&&<p>Reversal: {m.reversalReason}</p>}{m.status==='active'&&<CashierBankSettlementReview key={'settlement:'+actor+':'+m.id} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} match={m.id} deposit={m.deposit} statement={m.statement} amount={m.amount}/>}<CashierBankMatchReverse key={actor+":"+m.id} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} match={m.id} reversed={m.status==='reversed'} onSaved={()=>void load('report')}/></td><td><details><summary>View references</summary><p>Deposit: {m.deposit}</p><p>Statement: {m.statement}</p><p>Match: {m.id}</p><p>Recorded: {m.createdAt}</p></details></td></tr>)}</tbody></table></div>:<p>No matches on this page.</p>}{history.next&&<button disabled={busy} onClick={()=>void load('report',true)}>Next match page</button>}</>}</section>
}
